import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $ = (id) => document.getElementById(id);
const SIZE = 15;
const FLOOR_NAMES = ['THE ASHEN GATE','CINDER HALL','THE DROWNED ARCHIVE','BONE GALLERY','THE WARDEN’S KEEP','VEIL OF MOURNING','THE SUNKEN CHAPEL','ASHEN CATACOMBS','THE HOLLOW THRONE','HEART OF THE SPIRE'];
const FLOOR_COLORS = [0xd18c52,0xc96b4e,0x6c9ba0,0x9b8162,0xd4664f,0x7d719d,0x719b8d,0x9a684e,0x93808a,0xe5a34c];
let scene,camera,renderer,clock,worldGroup;
let floor=1,level=1,xp=0,maxHp=30,hp=30,attackPower=6,potions=2,playerPos={x:2,y:2},facing={x:0,y:1};
let map=[],enemies=[],enemyMeshes=[],playerMesh,stairsMesh,torches=[],particles=[];
let busy=false,started=false,gameEnded=false,soundOn=false,toastTimer;
const materialCache={};

function mat(color,roughness=.85,metalness=0,emissive=0,emissiveIntensity=0){const key=[color,roughness,metalness,emissive,emissiveIntensity].join('-');return materialCache[key]||(materialCache[key]=new THREE.MeshStandardMaterial({color,roughness,metalness,emissive,emissiveIntensity}));}
function init3D(){
  const canvas=$('game-canvas');renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});renderer.setPixelRatio(Math.min(window.devicePixelRatio||1,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;
  scene=new THREE.Scene();scene.background=new THREE.Color(0x10141b);scene.fog=new THREE.FogExp2(0x10141b,.033);
  camera=new THREE.PerspectiveCamera(42,1,.1,100);camera.position.set(9.7,12.6,14);camera.lookAt(7,0,7);
  scene.add(new THREE.HemisphereLight(0x9daebd,0x382a20,1.5));const key=new THREE.DirectionalLight(0xffdfb1,2.25);key.position.set(-5,12,8);key.castShadow=true;key.shadow.mapSize.set(1024,1024);key.shadow.camera.left=-12;key.shadow.camera.right=12;key.shadow.camera.top=12;key.shadow.camera.bottom=-12;scene.add(key);
  clock=new THREE.Clock();resize();window.addEventListener('resize',resize);animate();
}
function resize(){if(!renderer)return;const box=$('arena').getBoundingClientRect();const w=Math.max(1,box.width),h=Math.max(1,box.height);renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();}
function animate(){requestAnimationFrame(animate);if(!renderer)return;const t=clock.getElapsedTime();for(const torch of torches){torch.light.intensity=1.6+Math.sin(t*5+torch.offset)*.18;torch.flame.scale.y=.85+Math.sin(t*8+torch.offset)*.17;}if(playerMesh){playerMesh.rotation.y=THREE.MathUtils.lerp(playerMesh.rotation.y,Math.atan2(facing.x,facing.y),.15);playerMesh.position.y=.08+Math.sin(t*2.7)*.035;}renderer.render(scene,camera);}
function clearWorld(){if(worldGroup){scene.remove(worldGroup);worldGroup.traverse(o=>{if(o.geometry)o.geometry.dispose();});}worldGroup=new THREE.Group();scene.add(worldGroup);torches=[];enemyMeshes=[];particles=[];}
function box(parent,x,y,z,sx,sy,sz,material,cast=true,receive=true){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.castShadow=cast;m.receiveShadow=receive;parent.add(m);return m;}
function cellOpen(x,y){return x>=0&&y>=0&&x<SIZE&&y<SIZE&&map[y]?.[x]===0;}
function worldPos(p){return new THREE.Vector3(p.x-SIZE/2+.5,0,p.y-SIZE/2+.5);}
function buildMap(){map=Array.from({length:SIZE},(_,y)=>Array.from({length:SIZE},(_,x)=>(x===0||y===0||x===SIZE-1||y===SIZE-1)?1:0));
  // Deliberately broken-up pillars make the floors feel like rooms, while a central aisle stays traversable.
  for(let y=2;y<SIZE-2;y++)for(let x=2;x<SIZE-2;x++){if(Math.random()<.105&&Math.abs(x-7)>1&&Math.abs(y-7)>1&&!(x<4&&y<4))map[y][x]=1;}
  for(let i=0;i<5;i++){const x=3+Math.floor(Math.random()*9),y=3+Math.floor(Math.random()*9);if(!(x<5&&y<5))map[y][x]=1;}
  map[2][2]=0;map[SIZE-3][SIZE-3]=0;map[7][7]=0;for(let i=2;i<13;i++){map[7][i]=0;map[i][7]=0;}
}
function buildFloor(){clearWorld();buildMap();const tint=FLOOR_COLORS[(floor-1)%FLOOR_COLORS.length];const accent=new THREE.Color(tint);const floorMat=mat(0x282a2b,.97),wallMat=mat(0x343338,.92),wallTop=mat(0x45413c,.95),darkMat=mat(0x171a20,.9),goldMat=mat(tint,.45,.35,tint,.22);
  box(worldGroup,0,-.35,0,SIZE+.5,.6,SIZE+.5,mat(0x181a1d),false,true);
  for(let y=0;y<SIZE;y++)for(let x=0;x<SIZE;x++){const wx=x-SIZE/2+.5,wz=y-SIZE/2+.5;if(map[y][x]===0){box(worldGroup,wx,-.015,wz,.98,.12,.98,floorMat,false,true);if((x*13+y*7+floor)%11===0){box(worldGroup,wx,-.005,wz,.22,.015,.22,mat(0x3c3934),false,false);}}else{box(worldGroup,wx,.72,wz,1,1.65,1,wallMat,true,true);box(worldGroup,wx,1.56,wz,1.04,.12,1.04,wallTop,true,true);if((x*3+y*5)%4===0)box(worldGroup,wx,.36,wz,.78,.08,.78,darkMat,false,true);}}
